{
  "name": "pairwise_cost_gap_loss",
  "intuition": "This loss encourages the model to assign higher probabilities to options with lower cost gaps, aligning the preference with the objective of minimizing cost differences. By focusing on pairwise comparisons of cost gaps, it directly penalizes worse options relative to better ones, promoting preference alignment.",
  "pseudocode": "loss = mean( logsigmoid( (log_prob_w - log_prob_l) * scale * (cost_b - cost_a) ) )",
  "hyperparams": {
    "paradigm_family": "pairwise",
    "signal_family": "cost",
    "link_family": "logistic",
    "agg_family": "mean",
    "constraint_family": "none",
    "other_hparams": "scale=1.0"
  },
  "operators_used": ["logsigmoid"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "cost_a", "cost_b"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    scale = float(extra.get('scale', 1.0))\n    log_prob_w = batch['log_prob_w']\n    log_prob_l = batch['log_prob_l']\n    cost_a = batch['cost_a']\n    cost_b = batch['cost_b']\n    # Compute pairwise differences scaled by cost gap\n    diff = (log_prob_w - log_prob_l) * scale * (cost_b - cost_a)\n    loss = ops.mean(ops.logsigmoid(diff))\n    return loss"
}

{
  "name": "pairwise_cost_gap_pref",
  "intuition": "This loss encourages the model to prefer pairs with smaller cost gaps by penalizing larger differences, promoting more consistent and reliable preference signals. Using the cost gap directly aligns the loss with the objective of minimizing cost differences between options, which is effective in RL4CO settings.",
  "pseudocode": "scalar = mean( logsigmoid( - (log_prob_w - log_prob_l) * (cost_a - cost_b) / (abs(cost_gap) + epsilon) ) * weight )",
  "hyperparams": {
    "paradigm_family": "pairwise",
    "signal_family": "cost",
    "link_family": "gap",
    "agg_family": "mean",
    "constraint_family": "preference",
    "other_hparams": "epsilon=1e-6"
  },
  "operators_used": ["logsigmoid", "abs"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "cost_a", "cost_b", "cost_gap"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    epsilon = 1e-6\n    log_prob_w = batch['log_prob_w']\n    log_prob_l = batch['log_prob_l']\n    weight = batch['weight']\n    cost_a = batch['cost_a']\n    cost_b = batch['cost_b']\n    cost_gap = batch.get('cost_gap', ops.abs(cost_a - cost_b))\n    diff = log_prob_w - log_prob_l\n    cost_diff = cost_a - cost_b\n    penalty = ops.logsigmoid( - diff * cost_diff / (ops.abs(cost_gap) + epsilon) )\n    return ops.sum( penalty * weight ) / ops.size( penalty )"
}

{
  "name": "pairwise_cost_gap_loss",
  "intuition": "This loss encourages the model to assign higher log probabilities to lower-cost options by penalizing pairs where the higher-cost option has a higher likelihood. Using the cost gap as a signal aligns the model's preferences with cost minimization, promoting better ranking of options in RL4CO tasks.",
  "pseudocode": "loss = mean over pairs of max(0, log_prob_l - log_prob_w + alpha * cost_gap)",
  "hyperparams": {
    "paradigm_family": "ranking",
    "signal_family": "cost_difference",
    "link_family": "pairwise",
    "agg_family": "mean",
    "constraint_family": "cost_ordering",
    "other_hparams": "alpha as scale hyperparameter"
  },
  "operators_used": ["logsigmoid", "max", "mean"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "cost_gap"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    alpha = float(extra.get(\"alpha\", 1.0))\n    log_prob_w = batch[\"log_prob_w\"]\n    log_prob_l = batch[\"log_prob_l\"]\n    cost_gap = batch[\"cost_gap\"]\n    # Compute pairwise difference\n    diffs = log_prob_l - log_prob_w\n    # Compute hinge loss with cost gap scaled by alpha\n    loss_matrix = ops.maximum(0.0, diffs + alpha * cost_gap)\n    # Aggregate loss over pairs\n    loss = ops.mean(loss_matrix)\n    return loss"
}

{
  "name": "loss_rank_gap_tanh_advantage_fixed_grad",
  "intuition": "Fix rank_gap call by providing required cost_b signal, using advantage gap as cost proxy to softly penalize misrankings with tanh and relu, aggregated by weighted mean. Ensure output depends on log_prob_w to enable gradients.",
  "pseudocode": "cost_a = advantage_w; cost_b = advantage_l; gap = rank_gap(cost_a, cost_b); scaled_gap = scale * gap; base_loss = relu(tanh(scaled_gap)); grad_signal = log_prob_l - log_prob_w; loss = base_loss * sigmoid(grad_signal) * weight; loss = sum(loss) / sum(weight)",
  "hyperparams": {
    "paradigm_family": "rank_based",
    "signal_family": "advantage_gap",
    "link_family": "tanh",
    "agg_family": "weighted_sum",
    "constraint_family": "relu_nonneg"
  },
  "operators_used": ["rank_gap", "tanh", "relu", "mul", "sum", "div", "sub", "sigmoid"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "advantage_w", "advantage_l"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    eps = 1e-8\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    weight = batch.get('weight', lpw.new_ones(lpw.shape))\n    adv_w = batch['advantage_w']\n    adv_l = batch['advantage_l']\n    scale = float(extra.get('hyperparams', {}).get('scale', 1.0))\n    cost_a = adv_w\n    cost_b = adv_l\n    gap = ops.rank_gap(cost_a, cost_b)\n    scaled_gap = ops.mul(scale, gap)\n    base_loss = ops.relu(ops.tanh(scaled_gap))\n    grad_signal = ops.sub(lpl, lpw)  # encourages gradient flow\n    weight_sigmoid = ops.sigmoid(grad_signal)\n    loss_weighted = ops.mul(ops.mul(base_loss, weight_sigmoid), weight)\n    loss = ops.div(ops.sum(loss_weighted), ops.sum(weight).clamp(min=eps))\n    return loss\n"
}

{
  "name": "pairwise_logsigmoid_preference",
  "intuition": "This loss encodes preferences between pairs based on their log probabilities, encouraging the model to assign higher probability to preferred options. Using logsigmoid ensures smooth gradients and stability, while the pairwise structure directly optimizes relative rankings, making it effective for preference learning in RL4CO.",
  "pseudocode": "loss = sum(-logsigmoid(alpha * scale * (log_prob_w - log_prob_l) - beta * cost_gap))",
  "hyperparams": {
    "paradigm_family": "pairwise_margin",
    "signal_family": "preference_signal",
    "link_family": "logsigmoid",
    "agg_family": "pairwise",
    "constraint_family": "clamp_stabilized",
    "other_hparams": "optional"
  },
  "operators_used": ["logsigmoid", "clamp"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "cost_gap"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    weight = batch.get('weight', None)\n    alpha = float(extra.get('alpha', extra.get('hyperparams', {}).get('alpha', 1.0)))\n    scale = float(extra.get('hyperparams', {}).get('scale', 2.0))\n    cost_gap = batch['cost_gap']\n    x = alpha * scale * (lpw - lpl) - 0.5 * cost_gap\n    x = ops.clamp(x, -20.0, 20.0)\n    loss = -ops.logsigmoid(x)\n    if weight is not None:\n        loss = loss * weight\n    return loss.sum()"
}

