  "name": "pairwise_cost_gap_loss_normalized",
  "intuition": "Normalize the pairwise hinge loss by the sum of weights for stable training, replacing unsupported maximum with softplus.",
  "pseudocode": "loss = sum(softplus(log_prob_l - log_prob_w + alpha * cost_gap) * weight) / sum(weight)",
  "hyperparams": {
    "paradigm_family": "ranking",
    "signal_family": "cost_difference",
    "link_family": "hinge",
    "agg_family": "weighted_mean",
    "constraint_family": "normalization"
  },
  "operators_used": ["softplus", "sum"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "cost_gap"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    eps = 1e-8\n    alpha = float(extra.get(\"alpha\", 1.0))\n    log_prob_w = batch[\"log_prob_w\"]\n    log_prob_l = batch[\"log_prob_l\"]\n    cost_gap = batch[\"cost_gap\"]\n    weight = batch.get(\"weight\", log_prob_w.new_ones(log_prob_w.shape))\n    diffs = log_prob_l - log_prob_w + alpha * cost_gap\n    loss_matrix = ops.softplus(diffs)\n    weighted_loss = loss_matrix * weight\n    total_weight = ops.sum(weight).clamp(min=eps)\n    loss = ops.sum(weighted_loss) / total_weight\n    return loss"
}

