  },
  "code": "def generated_loss(batch, model_output, extra):\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    cost_gap = batch['cost_gap']\n    weight = batch.get('weight', None)\n    alpha = float(extra.get('alpha', extra.get('hyperparams', {}).get('alpha', 1.5)))\n    scale = float(extra.get('hyperparams', {}).get('scale', 3.0))\n    beta = float(extra.get('hyperparams', {}).get('beta', 0.5))\n    x = alpha * scale * (lpw - lpl) - beta * cost_gap\n    x = ops.clamp(x, -20.0, 20.0)\n    loss = -ops.logsigmoid(x)\n    if weight is not None:\n        loss = loss * weight\n    return loss.sum()"
