  "pseudocode": "norm_factor = max(abs(cost_gap)) + 1e-6\nscaled_cost_gap = cost_gap / norm_factor\nx = clamp(alpha * scale * (log_prob_w - log_prob_l) + bias, -20, 20)\nloss = -logsigmoid(x) * scaled_cost_gap * weight\nreturn sum(loss)",
