  "code": "def generated_loss(batch, model_output, extra):\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    weight = batch.get('weight', None)\n    cost_gap = batch['cost_gap']\n    alpha = float(extra.get('alpha', extra.get('hyperparams', {}).get('alpha', 1.0)))\n    scale = float(extra.get('hyperparams', {}).get('scale', 2.0))\n    bias = float(extra.get('hyperparams', {}).get('bias', 0.0))\n    max_cost_gap = ops.max(ops.abs(cost_gap)) + 1e-6\n    scaled_cost_gap = cost_gap / max_cost_gap\n    diff = alpha * scale * (lpw - lpl) + bias\n    x = ops.clamp(diff, -20.0, 20.0)\n    loss = -ops.logsigmoid(x) * scaled_cost_gap\n    if weight is not None:\n        loss = loss * weight\n    return loss.sum()"
