{
  "name": "pairwise_ranking_sigmoid_rankgap_weighted_v2_repaired",
  "intuition": "Use rank gap from advantages to weight pairwise sigmoid loss, with clamping and logsigmoid for numeric stability; ensure safe fallback and stable weighting.",
  "pseudocode": "adv_gap = clamp(advantage_w - advantage_l, 0, ∞)\nscore_diff = log_prob_w - log_prob_l\nlog_sigmoid_score = logsigmoid(score_diff)\nweighted_loss = -log_sigmoid_score * adv_gap * weight\nloss = mean(weighted_loss)",
  "hyperparams": {
    "paradigm_family": "pairwise_ranking",
    "signal_family": "advantage_gap",
    "link_family": "logsigmoid",
    "agg_family": "mean",
    "constraint_family": "normalization"
  },
  "operators_used": ["logsigmoid", "clamp", "sub", "mul", "neg", "mean"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "advantage_w", "advantage_l"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    eps = 1e-8\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    weight = batch.get('weight', ops.ones_like(lpw))\n    adv_w = batch['advantage_w']\n    adv_l = batch['advantage_l']\n    rank_gap_raw = ops.sub(adv_w, adv_l)\n    scaled_rank_gap = ops.clamp(rank_gap_raw, 0.0, None)\n    score_diff = ops.sub(lpw, lpl)\n    log_sigmoid_score = ops.logsigmoid(score_diff)\n    loss = ops.neg(log_sigmoid_score)\n    weighted_loss = ops.mul(loss, scaled_rank_gap)\n    weighted_loss = ops.mul(weighted_loss, weight)\n    return ops.mean(weighted_loss)"
}

{
  "name": "pairwise_regret_weighted_margin_hinge_loss_repair",
  "intuition": "Use delta_regret as weighting signal for hinge margin loss on scaled log-prob difference, clamp margin for numerical stability, mean loss for stable gradient.",
  "pseudocode": "margin = alpha * scale * (log_prob_w - log_prob_l) - beta * delta_regret\nmargin_clamped = clamp(margin, -20, 20)\nloss = relu(-margin_clamped) * weight\nreturn mean(loss)",
  "hyperparams": {
    "paradigm_family": "pairwise_margin_hinge",
    "signal_family": "regret_gap",
    "link_family": "hinge",
    "agg_family": "mean",
    "constraint_family": "clamp_and_relu"
  },
  "operators_used": ["relu", "clamp", "sub", "mul", "mean", "neg"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "delta_regret"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    eps = 1e-8\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    delta_regret = batch['delta_regret']\n    weight = batch.get('weight', ops.ones_like(delta_regret))\n    alpha = float(extra.get('alpha', 1.0))\n    scale = float(extra.get('hyperparams', {}).get('scale', 1.0))\n    beta = float(extra.get('beta', 1.0))\n\n    margin = ops.sub(ops.mul(alpha * scale, ops.sub(lpw, lpl)), ops.mul(beta, delta_regret))\n    margin_clamped = ops.clamp(margin, -20.0, 20.0)\n    loss = ops.mul(ops.relu(ops.neg(margin_clamped)), weight)\n    return ops.mean(loss)"
}

{
  "name": "builder_sampled_pairs_topk_cap_010",
  "intuition": "sampled pairs with top-k cap per batch to limit pairs by highest positive gap",
  "hyperparams": {
    "geometry_family": "sampled_pairs",
    "cap_family": "topk_per_batch",
    "weight_family": "uniform_none",
    "constraint_family": "budget_clamp"
  },
  "operators_used": [
    "sampled_pairs",
    "topk"
  ],
  "implementation_hint": {
    "expects": [
      "objective",
      "log_prob"
    ],
    "returns": "PrefBatch",
    "mode": "pairwise"
  },
  "code": "def generated_builder(feature_cache, extra):\n    objective = feature_cache['objective']\n    gap = objective[:, None, :] - objective[:, :, None]\n    mask = gap > 0.0\n    b_idx, winner_idx, loser_idx = mask.nonzero(as_tuple=True)\n    scores = gap[b_idx, winner_idx, loser_idx]\n    max_pairs = int(extra.get('max_pairs', 128))\n    if b_idx.numel() > max_pairs:\n        keep = torch.topk(scores, k=max_pairs, largest=True, sorted=False).indices\n        b_idx = b_idx[keep]\n        winner_idx = winner_idx[keep]\n        loser_idx = loser_idx[keep]\n    return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=None, meta={'builder': 'topk_per_batch', 'max_pairs': max_pairs})\n"
}

