{
  "name": "robust_combined_pairwise",
  "intuition": "Merges comprehensive all-pairs coverage with selective sampling based on gap thresholds, balancing robustness and diversity. Incorporates a minimal gap filter to focus on meaningful preferences while maintaining simplicity, improving stability against noise and stagnation.",
  "hyperparams": {
    "geometry_family": "dense_all_pairs",
    "cap_family": "budget_sample",
