    "returns": "PrefBatch",
    "mode": "pairwise"
  },
  "code": "def generated_builder(feature_cache, extra):\n    objective = feature_cache['objective']\n    mask_all = objective[:, :, None] < objective[:, None, :]\n    b_idx_all, winner_idx_all, loser_idx_all = mask_all.nonzero(as_tuple=True)\n    gap = objective[:, None, :] - objective[:, :, None]\n    thr = float(extra.get('gap_threshold', 0.1))\n    mask_gap = gap > thr\n    b_idx_gap, winner_idx_gap, loser_idx_gap = mask_gap.nonzero(as_tuple=True)\n    total_pairs = b_idx_gap.numel()\n    max_pairs = int(extra.get('max_pairs', 128))\n    if total_pairs < max_pairs:\n        remaining = max_pairs - total_pairs\n        indices = torch.randperm(b_idx_all.numel(), device=b_idx_all.device)[:remaining]\n        b_idx = torch.cat([b_idx_gap, b_idx_all[indices]])\n        winner_idx = torch.cat([winner_idx_gap, winner_idx_all[indices]])\n        loser_idx = torch.cat([loser_idx_gap, loser_idx_all[indices]])\n    else:\n        topk = torch.topk(gap[b_idx_gap, winner_idx_gap, loser_idx_gap], k=max_pairs, largest=True, sorted=False).indices\n        b_idx = b_idx_gap[topk]\n        winner_idx = winner_idx_gap[topk]\n        loser_idx = loser_idx_gap[topk]\n    return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=None, meta={'builder': 'robust_combined'})"
